H.background();
const a = P.a;
const v = H.plot2d({ xMin: -2, xMax: 6, yMin: -2, yMax: 12 });
v.grid(); v.axes();
// f(x) = (x^2 - a^2)/(x - a) = x + a  for x != a.  Hole at x=a, height 2a.
const L = 2 * a;
function f(x){ const den = x - a; return Math.abs(den) < 1e-6 ? NaN : (x * x - a * a) / den; }
v.fn(x => f(x), { color: H.colors.accent, width: 3 });
// The simplified line x + a (faint) — shows WHY the limit is 2a.
v.fn(x => x + a, { color: H.colors.sub, width: 1.5, dash: [6, 6] });
v.line(a, -2, a, 12, { color: H.colors.violet, width: 1, dash: [4, 4] });
v.line(-2, L, 6, L, { color: H.colors.violet, width: 1, dash: [4, 4] });
v.circle(a, L, 6, { stroke: H.colors.warn, width: 2.5, fill: H.colors.bg });
// Probe sliding toward x=a; the y-value never reaches but approaches 2a.
const d = 1.6 * (0.5 + 0.5 * Math.cos(t * 1.1));
const xp = a + (Math.sin(t * 0.7) >= 0 ? d : -d);
const yp = f(xp);
if (Number.isFinite(yp)){
  v.dot(xp, yp, { r: 6, fill: H.colors.good });
  v.line(xp, yp, a, L, { color: H.colors.good, width: 1, dash: [3, 3] });
}
H.text("Algebraic limit:  lim (x->a) (x^2 - a^2)/(x - a)", 24, 30, { color: H.colors.ink, size: 16, weight: 700 });
H.text("factor & cancel:  (x-a)(x+a)/(x-a) = x + a   ->   limit = " + L.toFixed(1), 24, 52, { color: H.colors.sub, size: 13 });
H.text("a = " + a.toFixed(1) + "    x = " + xp.toFixed(3) + "    f(x) = " + (Number.isFinite(yp) ? yp.toFixed(3) : "0/0"), 24, 74, { color: H.colors.good, size: 12 });
H.legend([{ label: "(x^2-a^2)/(x-a)", color: H.colors.accent }, { label: "x + a (cancelled)", color: H.colors.sub }], H.W - 200, 28);
